return items.map(item => {

  const text = item.json.output || item.json.text || '';

  let parsed;

  try {
    parsed = JSON.parse(text);
  } catch (e) {

    const match = text.match(/\{[\s\S]*\}/);

    if (match) {
      try {
        parsed = JSON.parse(match[0]);
      } catch {
        parsed = {};
      }
    } else {
      parsed = {};
    }
  }

  return {
    json: {
      reply: parsed.reply,
      email: parsed.email,
      budget: parsed.budget,
      location: parsed.location,
      property_type: parsed.property_type,
      lead_score: parsed.lead_score || "Cold",

      // مهم جدا
      conversation_history: item.json.conversation_history,
      message_text: item.json.message_text
    }
  };

});

return items.map(item => {
  return {
